// Custom Worker entry: the OpenNext fetch handler plus a cron that advances in-flight loads.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the bundle exists only after a build
// @ts-ignore -- generated by `opennextjs-cloudflare build`; absent before the first build
import { default as handler } from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,

  async scheduled(_event, env, ctx) {
    const request = new Request("https://internal/api/v1/internal/tick", {
      method: "POST",
      headers: { "x-tick-secret": (env as unknown as { TICK_SECRET?: string }).TICK_SECRET ?? "" },
    });
    ctx.waitUntil(handler.fetch(request, env, ctx));
  },
} satisfies ExportedHandler<CloudflareEnv>;
